static XMFLOAT3 add3(XMFLOAT3 a,XMFLOAT3 b){return{a.x+b.x,a.y+b.y,a.z+b.z};}
static XMFLOAT3 sub3(XMFLOAT3 a,XMFLOAT3 b){return{a.x-b.x,a.y-b.y,a.z-b.z};}
static XMFLOAT3 mul3(XMFLOAT3 a,float s){return{a.x*s,a.y*s,a.z*s};}
static float dot3(XMFLOAT3 a,XMFLOAT3 b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static XMFLOAT3 cross3(XMFLOAT3 a,XMFLOAT3 b){return{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}
static float len3(XMFLOAT3 a){return sqrtf(dot3(a,a));}
static XMFLOAT3 norm3(XMFLOAT3 a){float l=len3(a);return l>1e-6f?mul3(a,1.f/l):XMFLOAT3{0,0,0};}
static float clampf(float v,float a,float b){return (std::max)(a,(std::min)(b,v));}
static float smooth01(float x){x=clampf(x,0,1);return x*x*(3-2*x);}
static XMFLOAT3 rotY(XMFLOAT3 p,float a){float c=cosf(a),s=sinf(a);return{c*p.x+s*p.z,p.y,-s*p.x+c*p.z};}

static float hashf(float x,float z){float v=sinf(x*12.9898f+z*78.233f)*43758.5453f;return v-floorf(v);}
static float groundH(float x,float z){float h=sinf(x*.055f)*1.1f+cosf(z*.048f)*.9f+sinf((x+z)*.12f)*.32f+(hashf(floorf(x*.25f),floorf(z*.25f))-.5f)*.10f;return h*.34f;}
static XMFLOAT3 terrainNormal(float x,float z){float e=.15f,dx=groundH(x+e,z)-groundH(x-e,z),dz=groundH(x,z+e)-groundH(x,z-e);return norm3({-dx,2*e,-dz});}
