const char*vs=R"(cbuffer C:register(b0){matrix world;matrix view;matrix proj;float4 color;float3 lightDir;float useTex;}struct I{float3 p:POSITION;float3 n:NORMAL;float2 uv:TEXCOORD0;};struct O{float4 p:SV_POSITION;float3 n:NORMAL;float2 uv:TEXCOORD0;};O main(I i){O o;float4 wp=mul(float4(i.p,1),world);o.p=mul(mul(wp,view),proj);o.n=normalize(mul(float4(i.n,0),world).xyz);o.uv=i.uv;return o;})";
