static bool makeMesh(const std::vector<Vertex>&v,const std::vector<uint32_t>&i,MeshGPU&m,bool dyn=false){if(v.empty()||i.empty())return false;m.count=(UINT)i.size();m.bmin=m.bmax=v[0].p;for(const auto&a:v){m.bmin.x=(std::min)(m.bmin.x,a.p.x);m.bmin.y=(std::min)(m.bmin.y,a.p.y);m.bmin.z=(std::min)(m.bmin.z,a.p.z);m.bmax.x=(std::max)(m.bmax.x,a.p.x);m.bmax.y=(std::max)(m.bmax.y,a.p.y);m.bmax.z=(std::max)(m.bmax.z,a.p.z);}D3D11_BUFFER_DESC bd{};bd.ByteWidth=(UINT)(v.size()*sizeof(Vertex));bd.Usage=dyn?D3D11_USAGE_DYNAMIC:D3D11_USAGE_DEFAULT;bd.BindFlags=D3D11_BIND_VERTEX_BUFFER;bd.CPUAccessFlags=dyn?D3D11_CPU_ACCESS_WRITE:0;D3D11_SUBRESOURCE_DATA sd{};sd.pSysMem=v.data();if(FAILED(g_dev->CreateBuffer(&bd,dyn?nullptr:&sd,&m.vb)))return false;if(dyn){D3D11_MAPPED_SUBRESOURCE ms{};if(SUCCEEDED(g_ctx->Map(m.vb,0,D3D11_MAP_WRITE_DISCARD,0,&ms))){memcpy(ms.pData,v.data(),v.size()*sizeof(Vertex));g_ctx->Unmap(m.vb,0);}}bd={};bd.ByteWidth=(UINT)(i.size()*sizeof(uint32_t));bd.Usage=D3D11_USAGE_DEFAULT;bd.BindFlags=D3D11_BIND_INDEX_BUFFER;sd={};sd.pSysMem=i.data();return SUCCEEDED(g_dev->CreateBuffer(&bd,&sd,&m.ib));}
static bool loadOBJ(const std::wstring&wp,MeshGPU&m){std::ifstream f(wp);if(!f)return false;std::vector<XMFLOAT3>p,n;std::vector<XMFLOAT2>uv;std::vector<Vertex>v;std::vector<uint32_t>ind;std::unordered_map<std::string,uint32_t>map;std::string line;auto emit=[&](const std::string&s)->uint32_t{auto it=map.find(s);if(it!=map.end())return it->second;int pi=0,ti=0,ni=0;if(sscanf_s(s.c_str(),"%d/%d/%d",&pi,&ti,&ni)<1){sscanf_s(s.c_str(),"%d//%d",&pi,&ni);}Vertex a{};if(pi>0&&pi<=(int)p.size())a.p=p[pi-1];if(ni>0&&ni<=(int)n.size())a.n=n[ni-1];else a.n={0,1,0};if(ti>0&&ti<=(int)uv.size())a.uv=uv[ti-1];uint32_t id=(uint32_t)v.size();v.push_back(a);map[s]=id;return id;};while(std::getline(f,line)){std::istringstream ss(line);std::string t;ss>>t;if(t=="v"){XMFLOAT3 a;ss>>a.x>>a.y>>a.z;p.push_back(a);}else if(t=="vn"){XMFLOAT3 a;ss>>a.x>>a.y>>a.z;n.push_back(a);}else if(t=="vt"){XMFLOAT2 a;ss>>a.x>>a.y;a.y=1.f-a.y;uv.push_back(a);}else if(t=="f"){std::vector<std::string>face;std::string q;while(ss>>q)face.push_back(q);for(size_t k=1;k+1<face.size();++k){ind.push_back(emit(face[0]));ind.push_back(emit(face[k]));ind.push_back(emit(face[k+1]));}}}return makeMesh(v,ind,m,false);}
static void buildTerrain(){const int N=145;const float SIZE=128.f,step=SIZE/(N-1),half=SIZE*.5f;std::vector<Vertex>v;std::vector<uint32_t>i;v.reserve(N*N);for(int z=0;z<N;++z)for(int x=0;x<N;++x){float wx=-half+x*step,wz=-half+z*step;v.push_back({{wx,groundH(wx,wz),wz},terrainNormal(wx,wz),{wx*.075f,wz*.075f}});}for(int z=0;z<N-1;++z)for(int x=0;x<N-1;++x){uint32_t a=z*N+x;i.insert(i.end(),{a,a+N,a+1,a+1,a+N,a+N+1});}makeMesh(v,i,g_terrain,false);}
static void addSpring(uint32_t a,uint32_t b,float k,float damp){if(a==b||a>=g_nodes.size()||b>=g_nodes.size())return;float r=len3(sub3(g_nodes[b].p,g_nodes[a].p));g_springs.push_back({a,b,r,k,damp});}
static void computeCOM(){XMFLOAT3 p{0,0,0},v{0,0,0};float m=0;for(const auto&n:g_nodes){p=add3(p,mul3(n.p,n.mass));v=add3(v,mul3(n.v,n.mass));m+=n.mass;}if(m>0){g_com=mul3(p,1.f/m);g_comVel=mul3(v,1.f/m);}}
static void computeRestRms(){XMFLOAT3 s{0,0,0};for(uint32_t i=0;i<g_surfaceCount;++i){XMFLOAT3 r=sub3(g_nodes[i].p,g_nodes[g_core].p);s.x+=r.x*r.x;s.y+=r.y*r.y;s.z+=r.z*r.z;}float inv=1.f/float((std::max)(1u,g_surfaceCount));g_restRms={sqrtf(s.x*inv),sqrtf(s.y*inv),sqrtf(s.z*inv)};}
static void buildBlob(){const int LAT=20,LON=40;const float rx=2.25f,ry=1.32f,rz=1.90f;g_nodes.clear();g_blobVerts.clear();g_blobIndices.clear();g_springs.clear();float base=groundH(0,0)+1.42f;for(int la=0;la<=LAT;++la){float th=XM_PI*la/LAT;for(int lo=0;lo<=LON;++lo){float ph=XM_2PI*lo/LON,s=sinf(th);XMFLOAT3 q={rx*s*cosf(ph),ry*cosf(th),rz*s*sinf(ph)};float lump=1.f+.035f*sinf(ph*3.f+th*2.f)+.025f*cosf(ph*5.f-th);q=mul3(q,lump);Node nn{};nn.p={q.x,base+q.y,q.z};nn.mass=1.f;g_nodes.push_back(nn);g_blobVerts.push_back({nn.p,{0,1,0},{(float)lo/LON,(float)la/LAT}});}}g_surfaceCount=(uint32_t)g_nodes.size();Node core{};core.p={0,base,0};core.mass=8.f;g_core=(uint32_t)g_nodes.size();g_nodes.push_back(core);for(int la=0;la<LAT;++la)for(int lo=0;lo<LON;++lo){uint32_t a=la*(LON+1)+lo;g_blobIndices.insert(g_blobIndices.end(),{a,a+LON+1,a+1,a+1,a+LON+1,a+LON+2});}for(int la=0;la<=LAT;++la)for(int lo=0;lo<=LON;++lo){uint32_t a=la*(LON+1)+lo;if(lo<LON)addSpring(a,a+1,58.f,3.0f);if(la<LAT)addSpring(a,a+LON+1,58.f,3.0f);if(lo<LON&&la<LAT){addSpring(a,a+LON+2,36.f,2.3f);addSpring(a+1,a+LON+1,36.f,2.3f);}if(la+2<=LAT)addSpring(a,a+2*(LON+1),25.f,1.8f);if((la%2==0)&&(lo%2==0))addSpring(a,g_core,18.f,2.0f);}computeCOM();computeRestRms();g_cam={g_com.x,groundH(g_com.x,g_com.z)+.65f,g_com.z};makeMesh(g_blobVerts,g_blobIndices,g_blob,true);}
static float rheologyFactor(){computeCOM();float rel=0;for(uint32_t i=0;i<g_surfaceCount;++i)rel+=len3(sub3(g_nodes[i].v,g_comVel));rel/=float((std::max)(1u,g_surfaceCount));float rate=(std::max)(len3(g_comVel),rel*.75f);float shear=smooth01((rate-.65f)/2.6f);return 1.0f+5.8f*(std::max)(shear,g_hardening);}
static void applySpringForces(float stiff){for(const auto&s:g_springs){Node&a=g_nodes[s.a];Node&b=g_nodes[s.b];XMFLOAT3 d=sub3(b.p,a.p);float L=len3(d);if(L<1e-5f)continue;XMFLOAT3 n=mul3(d,1.f/L);float relv=dot3(sub3(b.v,a.v),n);float mag=(s.k*stiff)*(L-s.rest)+s.damp*(.8f+.35f*stiff)*relv;XMFLOAT3 f=mul3(n,mag);a.f=add3(a.f,f);b.f=sub3(b.f,f);}}
static void applyVolumePressure(float stiff){computeCOM();XMFLOAT3 ss{0,0,0};for(uint32_t i=0;i<g_surfaceCount;++i){XMFLOAT3 r=sub3(g_nodes[i].p,g_com);ss.x+=r.x*r.x;ss.y+=r.y*r.y;ss.z+=r.z*r.z;}float inv=1.f/float((std::max)(1u,g_surfaceCount));XMFLOAT3 rms={sqrtf(ss.x*inv),sqrtf(ss.y*inv),sqrtf(ss.z*inv)};float restVol=(std::max)(.001f,g_restRms.x*g_restRms.y*g_restRms.z);float volRatio=(rms.x*rms.y*rms.z)/restVol;float pressure=(1.f-volRatio)*105.f*(.70f+.11f*stiff);float verticalDef=(std::max)(0.f,g_restRms.y-rms.y);for(uint32_t i=0;i<g_surfaceCount;++i){XMFLOAT3 r=sub3(g_nodes[i].p,g_com);XMFLOAT3 dir=norm3({r.x/((std::max)(.08f,rms.x*rms.x)),r.y/((std::max)(.08f,rms.y*rms.y)),r.z/((std::max)(.08f,rms.z*rms.z))});g_nodes[i].f=add3(g_nodes[i].f,mul3(dir,pressure));if(verticalDef>0.02f){float sign=r.y>=0?1.f:-1.f;g_nodes[i].f.y+=sign*verticalDef*18.f*(.45f+.08f*stiff);}}}
static void applyActiveCirculation(float ix,float iz){float m=sqrtf(ix*ix+iz*iz);if(m<.001f)return;ix/=m;iz/=m;computeCOM();XMFLOAT3 axis=norm3({iz,0,-ix});const float drive=14.5f;XMFLOAT3 sum{0,0,0};std::vector<XMFLOAT3>af(g_surfaceCount);for(uint32_t i=0;i<g_surfaceCount;++i){XMFLOAT3 r=sub3(g_nodes[i].p,g_com);float surf=clampf(len3(r)/1.65f,.25f,1.f);af[i]=mul3(cross3(axis,r),drive*surf);sum=add3(sum,af[i]);}XMFLOAT3 mean=mul3(sum,1.f/float(g_surfaceCount));for(uint32_t i=0;i<g_surfaceCount;++i)g_nodes[i].f=add3(g_nodes[i].f,sub3(af[i],mean));}
static void collideGround(Node&n,float dt){float y=groundH(n.p.x,n.p.z)+.055f;if(n.p.y>=y)return;float impact=(std::max)(0.f,-n.v.y);g_hardening=(std::max)(g_hardening,smooth01((impact-1.0f)/3.3f));n.p.y=y;float restitution=.02f+.18f*smooth01((impact-1.2f)/3.8f);if(n.v.y<0)n.v.y=-n.v.y*restitution;float mu=.62f+.18f*g_hardening;float tang=sqrtf(n.v.x*n.v.x+n.v.z*n.v.z);float maxDv=mu*(impact+9.81f*dt);if(tang>1e-5f){float dv=(std::min)(tang,maxDv);float k=(tang-dv)/tang;n.v.x*=k;n.v.z*=k;}}
static void collideObject(Node&n,const SceneObj&o){if(!o.collider||!o.mesh||o.mesh->count==0)return;XMFLOAT3 origin{o.x,groundH(o.x,o.z),o.z};XMFLOAT3 local=rotY(sub3(n.p,origin),-o.yaw);local=mul3(local,1.f/o.scale);const float pad=.045f/o.scale;XMFLOAT3 mn={o.mesh->bmin.x-pad,o.mesh->bmin.y-pad,o.mesh->bmin.z-pad},mx={o.mesh->bmax.x+pad,o.mesh->bmax.y+pad,o.mesh->bmax.z+pad};if(local.x<mn.x||local.x>mx.x||local.y<mn.y||local.y>mx.y||local.z<mn.z||local.z>mx.z)return;float d[6]={local.x-mn.x,mx.x-local.x,local.y-mn.y,mx.y-local.y,local.z-mn.z,mx.z-local.z};int face=0;for(int i=1;i<6;++i)if(d[i]<d[face])face=i;XMFLOAT3 nl{0,0,0};float push=d[face]+pad;switch(face){case 0:nl={-1,0,0};break;case 1:nl={1,0,0};break;case 2:nl={0,-1,0};break;case 3:nl={0,1,0};break;case 4:nl={0,0,-1};break;default:nl={0,0,1};break;}local=add3(local,mul3(nl,push));n.p=add3(origin,rotY(mul3(local,o.scale),o.yaw));XMFLOAT3 nw=rotY(nl,o.yaw);float vn=dot3(n.v,nw);float impact=(std::max)(0.f,-vn);float hard=smooth01((impact-.9f)/3.0f);g_hardening=(std::max)(g_hardening,hard);if(vn<0){float restitution=.01f+.30f*hard;n.v=sub3(n.v,mul3(nw,(1.f+restitution)*vn));}XMFLOAT3 tangent=sub3(n.v,mul3(nw,dot3(n.v,nw)));float slide=.93f-.30f*hard;n.v=sub3(n.v,mul3(tangent,1.f-slide));}
static void physicsStep(float dt,float ix,float iz){g_hardening=(std::max)(0.f,g_hardening-dt*.75f);float stiff=rheologyFactor();for(auto&n:g_nodes)n.f={-.16f*n.v.x,-9.81f*n.mass-.16f*n.v.y,-.16f*n.v.z};applySpringForces(stiff);applyVolumePressure(stiff);applyActiveCirculation(ix,iz);for(size_t i=0;i<g_nodes.size();++i){Node&n=g_nodes[i];XMFLOAT3 a=mul3(n.f,1.f/n.mass);n.v=add3(n.v,mul3(a,dt));float sp=len3(n.v);if(sp>11.f)n.v=mul3(n.v,11.f/sp);n.p=add3(n.p,mul3(n.v,dt));if(i<g_surfaceCount){collideGround(n,dt);for(const auto&o:g_scene)collideObject(n,o);}}computeCOM();}
static void updateBlobMesh(){if(g_blobVerts.size()!=g_surfaceCount)return;for(uint32_t i=0;i<g_surfaceCount;++i){g_blobVerts[i].p=g_nodes[i].p;g_blobVerts[i].n={0,0,0};}for(size_t t=0;t+2<g_blobIndices.size();t+=3){uint32_t ia=g_blobIndices[t],ib=g_blobIndices[t+1],ic=g_blobIndices[t+2];XMFLOAT3 a=g_blobVerts[ia].p,b=g_blobVerts[ib].p,c=g_blobVerts[ic].p;XMFLOAT3 nn=cross3(sub3(b,a),sub3(c,a));g_blobVerts[ia].n=add3(g_blobVerts[ia].n,nn);g_blobVerts[ib].n=add3(g_blobVerts[ib].n,nn);g_blobVerts[ic].n=add3(g_blobVerts[ic].n,nn);}for(auto&v:g_blobVerts)v.n=norm3(v.n);D3D11_MAPPED_SUBRESOURCE ms{};if(SUCCEEDED(g_ctx->Map(g_blob.vb,0,D3D11_MAP_WRITE_DISCARD,0,&ms))){memcpy(ms.pData,g_blobVerts.data(),g_blobVerts.size()*sizeof(Vertex));g_ctx->Unmap(g_blob.vb,0);}}
static void update(float dt){float ix=0,iz=0;if(g_keys['A']||g_keys[VK_LEFT])ix-=1;if(g_keys['D']||g_keys[VK_RIGHT])ix+=1;if(g_keys['W']||g_keys[VK_UP])iz+=1;if(g_keys['S']||g_keys[VK_DOWN])iz-=1;if(ix&&iz){ix*=.7071067f;iz*=.7071067f;}const int sub=10;float h=dt/sub;for(int i=0;i<sub;++i)physicsStep(h,ix,iz);updateBlobMesh();float ck=1.f-expf(-4.2f*dt);g_cam.x+=(g_com.x-g_cam.x)*ck;g_cam.z+=(g_com.z-g_cam.z)*ck;g_cam.y=groundH(g_cam.x,g_cam.z)+.65f;}
static XMMATRIX objectWorld(const SceneObj&o){return XMMatrixScaling(o.scale,o.scale,o.scale)*XMMatrixRotationY(o.yaw)*XMMatrixTranslation(o.x,groundH(o.x,o.z),o.z);}
static void drawMesh(const MeshGPU&m,const XMMATRIX&w,const XMFLOAT4&c,float useTex,ID3D11ShaderResourceView*srv){if(!m.vb||!m.ib||m.count==0)return;UINT st=sizeof(Vertex),off=0;g_ctx->IASetVertexBuffers(0,1,&m.vb,&st,&off);g_ctx->IASetIndexBuffer(m.ib,DXGI_FORMAT_R32_UINT,0);g_ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);float ty=groundH(g_cam.x,g_cam.z)+.55f;XMVECTOR eye=XMVectorSet(g_cam.x-20.f*g_zoom,ty+22.f*g_zoom,g_cam.z-20.f*g_zoom,1),at=XMVectorSet(g_cam.x+1.4f,ty,g_cam.z+1.4f,1),up=XMVectorSet(0,1,0,0);XMMATRIX view=XMMatrixLookAtLH(eye,at,up),proj=XMMatrixPerspectiveFovLH(XMConvertToRadians(42.f),g_w/(float)(std::max)(1,g_h),.1f,240.f);CB cb{};cb.world=XMMatrixTranspose(w);cb.view=XMMatrixTranspose(view);cb.proj=XMMatrixTranspose(proj);cb.color=c;cb.lightDir={-.55f,-1.f,.35f};cb.useTex=useTex;g_ctx->UpdateSubresource(g_cb,0,nullptr,&cb,0,0);g_ctx->VSSetConstantBuffers(0,1,&g_cb);g_ctx->PSSetConstantBuffers(0,1,&g_cb);g_ctx->PSSetShaderResources(0,1,&srv);g_ctx->PSSetSamplers(0,1,&g_sampler);g_ctx->DrawIndexed(m.count,0,0);}
