static void buildScene(){g_scene.clear();auto add=[&](MeshGPU&m,float x,float z,float yaw,float s,bool c=true){g_scene.push_back({&m,x,z,yaw,s,c});};add(g_crates,-18,14,.25f,1.45f);add(g_barrel,-11,17,-.5f,1.5f);add(g_rubble,-4,15,.8f,1.55f);add(g_barrel,8,17,.15f,1.45f);add(g_crates,18,13,-.65f,1.35f);add(g_rubble,-23,5,1.7f,1.25f);add(g_barrel,-13,6,.2f,1.55f);add(g_crates,14,6,.55f,1.25f);add(g_rubble,24,4,-.8f,1.45f);add(g_floor,-22,-5,0,2.0f,false);add(g_floorRocky,22,-6,.6f,2.0f,false);add(g_barrel,-16,-8,.9f,1.5f);add(g_rubble,-7,-7,2.2f,1.30f);add(g_crates,9,-9,-.3f,1.40f);add(g_barrel,18,-11,.4f,1.45f);add(g_rubble,-26,-18,.3f,1.6f);add(g_crates,-14,-19,.7f,1.3f);add(g_barrel,-3,-20,-.2f,1.55f);add(g_rubble,10,-18,1.1f,1.35f);add(g_crates,24,-19,-.45f,1.45f);add(g_floorRocky,-32,24,.1f,1.9f,false);add(g_floor,31,22,-.4f,2.1f,false);add(g_rubble,33,-2,.6f,1.4f);add(g_barrel,30,11,-.3f,1.5f);add(g_crates,-31,11,.5f,1.35f);}
